<section class="metric-grid" aria-label="Chatbot session summary"><article class="metric-card"><span>Sessions</span><strong><?= $escape(number_format($analytics->sessions)) ?></strong><small><?= $escape(number_format($analytics->activeSessions)) ?> active across <?= $escape(number_format($analytics->distinctChatbots)) ?> chatbots</small></article><article class="metric-card"><span>User messages</span><strong><?= $escape(number_format($analytics->messages)) ?></strong><small><?= $escape(number_format($analytics->failedAssistantMessages)) ?> failed assistant outcomes</small></article><article class="metric-card"><span>Provider tokens</span><strong><?= $escape(number_format($analytics->providerTokens)) ?></strong><small>Installation usage, not monetary cost</small></article><article class="metric-card"><span>Traffic mix</span><strong><?= $escape(number_format($analytics->productionSessions)) ?> / <?= $escape(number_format($analytics->testSessions)) ?></strong><small>production / test sessions</small></article></section>
<div class="section-heading"><h2>Daily activity</h2><p>At most 90 rows; message content and visitor identifiers are excluded.</p></div><?php if($analytics->daily===[]):?><section class="empty-state compact-empty"><h3>No sessions in this window</h3></section><?php else:?><div class="table-card"><table><thead><tr><th>UTC day</th><th>Sessions</th><th>User messages</th><th>Provider tokens</th></tr></thead><tbody><?php foreach($analytics->daily as $metric):?><tr><td><?= $escape($metric['day']) ?></td><td><?= $escape(number_format($metric['sessions'])) ?></td><td><?= $escape(number_format($metric['messages'])) ?></td><td><?= $escape(number_format($metric['provider_tokens'])) ?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?>
